int interpolationSearch(int a[], int n, int t) {
    int lo=0, hi=n-1;
    while(lo<=hi&&t>=a[lo]&&t<=a[hi]){
        if(lo==hi) return a[lo]==t?lo:-1;
        int pos=lo+((long)(t-a[lo])*(hi-lo))/(a[hi]-a[lo]);
        if(a[pos]==t) return pos;
        if(a[pos]<t) lo=pos+1; else hi=pos-1;
    }
    return -1;
}
